-- Creacion de Triggers Vistas Analitcas Replica OPTIMUS
-- Orden_Asignacion

DROP TRIGGER  "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaInsertTablaOrden_Asignacion"; GO 

CREATE TRIGGER "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaInsertTablaOrden_Asignacion"
 AFTER   INSERT ON "BSCL.Orden.BD::ORD.Asignacion"
 REFERENCING NEW ROW NewRow FOR EACH ROW 
 BEGIN
	INSERT INTO "BSCL.Plataforma.BD::PLA.Replica.WorkStack"("Key", "Table","Action" , "Status", "Stamp"  )
	SELECT cast(:NewRow."IdAsignacion" AS varchar(200)),'Orden_Asignacion', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY;
 END; GO

 DROP TRIGGER  "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaUpdateTablaOrden_Asignacion"; GO 

CREATE TRIGGER "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaUpdateTablaOrden_Asignacion"
 AFTER   UPDATE ON "BSCL.Orden.BD::ORD.Asignacion"
 REFERENCING NEW ROW NewRow FOR EACH ROW 
 BEGIN
 	INSERT INTO "BSCL.Plataforma.BD::PLA.Replica.WorkStack"("Key", "Table","Action" , "Status", "Stamp"  )
	SELECT cast(:NewRow."IdAsignacion" AS varchar(200)),'Orden_Asignacion', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY;
END; GO

 DROP TRIGGER  "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaDeleteTablaOrden_Asignacion"; GO
 
 CREATE TRIGGER "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaDeleteTablaOrden_Asignacion"
 AFTER   DELETE ON "BSCL.Orden.BD::ORD.Asignacion"
 REFERENCING OLD ROW OldRow FOR EACH ROW 
 BEGIN
	INSERT INTO "BSCL.Plataforma.BD::PLA.Replica.WorkStack"("Key", "Table","Action" , "Status", "Stamp"  )
	SELECT cast(:OldRow."IdAsignacion" AS varchar(200)),'Orden_Asignacion', 'D', 0,  CURRENT_TIMESTAMP  FROM DUMMY;
END; GO
 
