 SET SCHEMA "BSCL"; GO 

DROP TRIGGER  "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaInsertTablaCuentaBancaria"; GO

CREATE TRIGGER "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaInsertTablaCuentaBancaria"
 AFTER   INSERT ON "BSCL.SocioNegocio.BD::PER.CuentaBancaria"
 REFERENCING NEW ROW NewRow FOR EACH ROW 
 BEGIN
  	INSERT INTO "BSCL.Plataforma.BD::PLA.Replica.WorkStack"("Key", "Table","Action" , "Status", "Stamp"  )
	SELECT cast(:NewRow."IdCuentaBancaria" AS varchar(200)),'SocioNegocio_PersonaCuentaBancaria', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY;
 END; GO
 
 DROP TRIGGER  "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaUpdateTablaCuentaBancaria"; GO

CREATE TRIGGER "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaUpdateTablaCuentaBancaria"
 AFTER   UPDATE ON "BSCL.SocioNegocio.BD::PER.CuentaBancaria"
 REFERENCING NEW ROW NewRow FOR EACH ROW 
 BEGIN
	/* 
  	INSERT INTO "BSCL.Plataforma.BD::PLA.Replica.WorkStack"("Key", "Table","Action" , "Status", "Stamp"  )
	SELECT cast(:NewRow."IdCuentaBancaria" AS varchar(200)),'SocioNegocio_PersonaCuentaBancaria', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY;
	*/
	INSERT INTO "BSCL.Plataforma.BD::PLA.Replica.WorkStack"("Key", "Table","Action" , "Status", "Stamp"  )
	SELECT cast(:NewRow."IdCuentaBancaria" AS varchar(200)),'SocioNegocio_PersonaCuentaBancaria', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY WHERE :NewRow."Borrado" = 'N'
	UNION
	SELECT cast(:NewRow."IdCuentaBancaria" AS varchar(200)),'SocioNegocio_PersonaCuentaBancaria', 'D', 0,  CURRENT_TIMESTAMP  FROM DUMMY WHERE :NewRow."Borrado" = 'S';
 END; GO

