 END; GO

 DROP TRIGGER  "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaUpdateTablaDireccionFisica"; GO

CREATE TRIGGER "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaUpdateTablaDireccionFisica"
 AFTER   UPDATE ON "BSCL.SocioNegocio.BD::PER.DireccionFisica"
 REFERENCING NEW ROW NewRow FOR EACH ROW 
 BEGIN
	 /*
 	INSERT INTO "BSCL.Plataforma.BD::PLA.Replica.WorkStack"("Key", "Table","Action" , "Status", "Stamp"  )
	SELECT cast(:NewRow."IdDireccionFisica" AS varchar(200)),'SocioNegocio_PersonaDireccionFisica', CASE :NewRow."IdEstado" WHEN 'VIG' THEN 'A' ELSE 'D' END, 0,  CURRENT_TIMESTAMP  FROM DUMMY;
	*/
	INSERT INTO "BSCL.Plataforma.BD::PLA.Replica.WorkStack"("Key", "Table","Action" , "Status", "Stamp"  )
	SELECT cast(:NewRow."IdDireccionFisica" AS varchar(200)),'SocioNegocio_PersonaDireccionFisica', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY WHERE :NewRow."Borrado" = 'N'
	UNION
	SELECT cast(:NewRow."IdDireccionFisica" AS varchar(200)),'SocioNegocio_PersonaDireccionFisica', 'D', 0,  CURRENT_TIMESTAMP  FROM DUMMY WHERE :NewRow."Borrado" = 'S'
	UNION
	SELECT CAST(:NewRow."IdPersona" AS varchar(200)), 'SocioNegocio_Cliente', 'A', 0, CURRENT_TIMESTAMP FROM DUMMY;
 END; GO

