 BEGIN
 	INSERT INTO "BSCL.Plataforma.BD::PLA.Replica.WorkStack"("Key", "Table","Action" , "Status", "Stamp"  )
	SELECT cast(:OldRow."IdTelefono" AS varchar(200)),'SocioNegocio_PersonaTelefono', 'D', 0,  CURRENT_TIMESTAMP  FROM DUMMY;

 END; GO
 
