 -- CARTERAHIS

/*DROP TRIGGER  "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaInsertTablaCustodia_CarteraHis"; GO

CREATE TRIGGER "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaInsertTablaCustodia_CarteraHis"
 AFTER   INSERT ON "BSCL.Custodia.BD::HIS.Cartera"
 REFERENCING NEW ROW NewRow FOR EACH ROW 
 BEGIN 
	INSERT INTO "BSCL.Plataforma.BD::PLA.Replica.WorkStack"("Key", "Table","Action" , "Status", "Stamp"  )
	SELECT cast(:NewRow."IdCartera" AS varchar(200)),'Custodia_CarteraFMHis', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY WHERE :NewRow."IdClasificacionTipoInstrumento" = 'FM'
	UNION
	SELECT cast(:NewRow."IdCartera" AS varchar(200)),'Custodia_CarteraRFIFHis', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY WHERE :NewRow."IdClasificacionTipoInstrumento" IN ('RF','IF')
	UNION
	SELECT cast(:NewRow."IdCartera" AS varchar(200)),'Custodia_CarteraRVHis', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY WHERE :NewRow."IdClasificacionTipoInstrumento" = 'RV'
	UNION
	SELECT cast(:NewRow."IdCartera" AS varchar(200)),'Custodia_CarteraOtrosProductosHis', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY WHERE :NewRow."IdClasificacionTipoInstrumento" NOT IN ('RV','RF','IF','FM')
	UNION
	SELECT cast(:NewRow."IdPortafolio" || ':' || :NewRow."Nemotecnico" || ':' || :NewRow."FechaRespaldo" AS varchar(200)),'Custodia_CustodiaHis', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY WHERE :NewRow."IdClasificacionTipoInstrumento" NOT IN ('RV','RF','IF','FM');		   
 END; GO
 
